(function(w){
  const meta={success:{title:'Éxito',icon:'✓'},error:{title:'Error',icon:'!'},danger:{title:'Peligro',icon:'!'},info:{title:'Información',icon:'i'},warning:{title:'Advertencia',icon:'!'}};
  function root(){let el=document.querySelector('.notify-stack');if(!el){el=document.createElement('div');el.className='notify-stack';el.setAttribute('aria-live','polite');el.setAttribute('aria-atomic','false');document.body.appendChild(el)}return el}
  w.showNotify=function(message,type='info',options={}){type=meta[type]?type:'info';const cfg=meta[type],item=document.createElement('div');item.className='notify-item '+type;item.setAttribute('data-no-action-icon','1');item.setAttribute('role',(type==='error'||type==='danger')?'alert':'status');const stack=root();stack.querySelectorAll('.notify-item').forEach(old=>old.remove());const icon=document.createElement('div');icon.className='notify-icon';icon.textContent=cfg.icon;const copy=document.createElement('div');copy.className='notify-copy';const strong=document.createElement('strong');strong.textContent=options.title||cfg.title;const span=document.createElement('span');span.textContent=String(message||'');copy.append(strong,span);const close=document.createElement('button');close.type='button';close.className='notify-close';close.setAttribute('data-no-action-icon','1');close.setAttribute('tabindex','-1');close.setAttribute('aria-label','Cerrar notificación');close.textContent='×';item.append(icon,copy,close);stack.appendChild(item);let timer;const remove=()=>{clearTimeout(timer);item.classList.add('is-leaving');setTimeout(()=>item.remove(),220)};close.addEventListener('click',remove);timer=setTimeout(remove,Math.max(2200,Number(options.duration||4600)));return item};
})(window);
